def write_chapters(g):
    globals().update(g)
    chapter(1,'Giới thiệu dự án',
      'Giải thích bài toán, nguồn WESAD, ý nghĩa cảm biến và ranh giới giữa mục tiêu nghiên cứu với kết quả đã có.',[
      'Nhận diện căng thẳng (stress recognition) ở đây là phân loại một cửa sổ tín hiệu thành ba trạng thái của giao thức thu thập. Mô hình học từ nhãn thí nghiệm, không trực tiếp đo một khái niệm căng thẳng tuyệt đối cho mọi người và mọi hoàn cảnh.',
      'WESAD là bộ dữ liệu wearable stress and affect detection. Một subject là một người tham gia, có nhiều chuỗi tín hiệu và nhãn theo thời gian. Cùng một người tạo nhiều cửa sổ; những cửa sổ ấy không phải những người độc lập.',
      'ACC là gia tốc, cung cấp chuyển động theo ba trục. BVP là tín hiệu thể tích xung máu quang học; EDA phản ánh độ dẫn điện da. Chúng có thể chứa thông tin liên quan trạng thái sinh lý nhưng cũng chịu tác động chuyển động, tư thế và đặc điểm cá nhân. Đây là giải thích nền tảng, không phải kết luận nhân quả từ điểm số mô hình.'])
    h2('C. Liên hệ codebase'); source('README.md',('src/evaluation/metrics.py','classification_metrics'),'configs/default.yaml','experiments/e1_cnn/baseline_registry.json')
    table('Nhãn khoa học và chỉ số lớp',['Nhãn WESAD','Nhãn trong model','Diễn giải'],[(1,0,'baseline: trạng thái nền'),(2,1,'stress: giai đoạn gây căng thẳng'),(3,2,'amusement: giai đoạn vui vẻ'),('Các giá trị khác','-1 trong timeline','Loại khi căn nhãn; không phải lớp thứ tư')],[3,4.5,9.5])
    h2('D. Phân tích hoạt động'); p('Mục tiêu phần mềm là duy trì chuỗi truy xuất: cấu hình → dữ liệu đã xử lý → split → huấn luyện → dự đoán → kết quả. Mục tiêu nghiên cứu là so sánh khả năng tổng quát hóa sang người chưa có trong Train của CNN, GRU, CNN-GRU và thiết kế loại cảm biến. Có pipeline chạy được chưa đồng nghĩa đã trả lời đầy đủ các câu hỏi nghiên cứu.')
    p('CNN-1D học mẫu cục bộ theo thời gian bằng bộ lọc dùng chung. GRU duy trì trạng thái ẩn khi đọc chuỗi và có thể học phụ thuộc thời gian. CNN-GRU thường ghép hai ý tưởng ấy; trong dự án này module hybrid chưa có triển khai. Deep Learning giúp học biểu diễn từ các kênh đồng bộ nhưng không bảo đảm hơn các baseline khác nếu dữ liệu hoặc giao thức chưa phù hợp.')
    p('Baseline là một thiết kế và hồ sơ kết quả được giữ cố định để đối chiếu. Experiment là thiết kế kiểm chứng một giả thuyết, còn một lượt thực thi được phân biệt bằng GROUP_ID. E1 chính thức đã finalized; E2 có một lượt đủ năm folds; E3 và sensor ablation chưa có kết quả. Các lượt CNN ngày 15/11 phải giữ danh tính riêng với E1 ngày 08/11.')
    ending('Ví dụ minh họa: một đoạn 30 giây của S2 tạo tensor 5 × 960. Model trả ba logits, chẳng hạn [0.1, 1.2, −0.3]; argmax là chỉ số 1, tức stress. Các logits này là số giả định để học cách đọc đầu ra, không phải dự đoán WESAD đã lưu.',
      'Bài toán là phân loại ba trạng thái từ tín hiệu cổ tay trên người chưa thấy. Thiết kế đánh giá và danh tính artifacts quan trọng ngang với kiến trúc mạng.',
      ['Vì sao 2.136 cửa sổ không tương đương 2.136 người độc lập?','Nhãn 1 trong file gốc khác nhãn 1 trong Dataset thế nào?','E2 đã có kết quả có đủ để kết luận GRU kém CNN trong mọi cấu hình không?'])

    chapter(2,'Hướng dẫn đọc cấu trúc dự án','Tìm đúng nơi để đọc logic, tham số, dữ liệu và bằng chứng; hiểu package, module, import và entry point.',[
      'Một module Python thường là một tệp .py. Package là một nhóm module có thể import; các tệp __init__.py hiện diện để xác lập package. Entry point là điểm bắt đầu khi gọi một lệnh, thường là main() được bảo vệ bằng điều kiện __name__ == "__main__".',
      'Tổ chức tách src, scripts và configs giúp thuật toán có thể tái sử dụng và kiểm thử độc lập với lệnh terminal. Đây là suy luận từ cấu trúc: src chứa thao tác, scripts điều phối thao tác, còn YAML mô tả lựa chọn cho từng experiment.'])
