    chapter(5,'Hiểu dữ liệu WESAD','Đọc cấu trúc một subject, shape/rate/duration và phân tích đầy đủ ba hàm inspection mà không cần nạp raw trong lần học đầu.',[
      'Chuỗi nhiều kênh thường có shape [thời gian, kênh]. Cùng một thời lượng nhưng tần số khác nhau dẫn tới số hàng khác nhau. NumPy dtype quyết định cách biểu diễn và dung lượng; shape không mang đơn vị thời gian nếu chưa biết sampling rate.',
      'Một kênh là một đại lượng số theo thời gian; một sensor có thể sinh nhiều kênh. ACC gồm ba trục nên một sensor ACC góp ba input channels. Tensor shape là thứ tự các chiều, không chỉ là tổng số phần tử.'])
    h2('C. Liên hệ codebase'); source(('src/data/inspection.py','load_subject'),('src/data/inspection.py','inspect_subject'),('src/data/inspection.py','inspect_dataset'),'data/interim/inspection.json')
    h2('D. Phân tích hoạt động'); h3('5.1. Cấu trúc và ví dụ thật S2 từ metadata')
    p('load_subject kỳ vọng dict có signal, label, subject. signal phân theo wrist và chest. RATES khai báo wrist: ACC 32, BVP 64, EDA 4, TEMP 4 Hz; chest có ACC/ECG/EMG/EDA/Temp/Resp ở 700 Hz. Chú ý Temp phía chest và TEMP phía wrist khác chữ hoa. E1/E2 chỉ lấy wrist ACC/BVP/EDA; inspection vẫn thống kê cả những kênh không đưa vào model.')
    table('S2 đã ghi trong inspection.json, không nạp lại pickle',['Trường','Shape / rate','Cách đọc'],[
      ('label','[4.255.300], int32; 700 Hz','4.255.300 / 700 = 6.079 giây'),('wrist ACC','[194.528, 3]; 32 Hz','194.528 mốc thời gian; ba giá trị tại mỗi mốc'),('wrist BVP','[389.056, 1]; 64 Hz','Cùng 6.079 giây; nhiều hàng gấp đôi ACC'),('wrist EDA / TEMP','[24.316, 1]; 4 Hz','Cùng thời lượng, không thể ghép hàng trực tiếp với ACC'),('chest ACC','[4.255.300, 3]; 700 Hz','Được kiểm tra, không đưa vào baseline hiện tại'),('cache windows S2','[137, 5, 960], float32','137 cửa sổ; labels 0/1/2 có số lượng 75/39/23')],[3.8,6,7.2])
    p('Các con số là nội dung báo cáo đã lưu, được đối chiếu với metadata processed. Chúng không phải kết quả đọc raw mới. S2 wrist ACC có min −128 và max 127 trong báo cáo; không được tự diễn giải chúng thành m/s² hay g khi code không có bước chuyển đơn vị. range_policy nói rõ chỉ ghi miền quan sát, không clipping sinh lý hoặc đổi đơn vị.')
    h3('5.2. load_subject(root, subject)'); p('Input là Path gốc dữ liệu và ID như S2. Hàm xây đường dẫn S2/S2.pkl, pickle.load(..., encoding="latin1"), kiểm tra ba khóa bắt buộc và identity data["subject"] khớp ID. Output là dict raw. File thiếu gây FileNotFoundError; thiếu khóa hoặc sai identity gây ValueError; lỗi giải mã pickle có thể truyền lên. Hàm này được inspect_dataset và prepare_subject gọi, cùng audit_preprocessing. Trong nhiệm vụ biên soạn không gọi hàm vì cần bảo toàn phạm vi không nạp pickle.')
    h3('5.3. inspect_subject(data, subject)'); p('Hàm chuyển labels sang NumPy, yêu cầu một chiều, hữu hạn và mọi giá trị thuộc 0..7. Với từng tín hiệu, yêu cầu mảng hai chiều không rỗng, ACC có ba cột còn cảm biến khác một cột. Tính finite theo block tối đa 100.000 hàng để tránh tạo một mảng boolean quá lớn. Thời lượng len(signal)/rate phải gần len(labels)/700 trong dung sai 1/rate + 1/700. Cuối cùng phải có wrist ACC/BVP/EDA. Output là dict gồm keys, label counts/shape/dtype/rate, duration và thống kê từng signal: shape, dtype, rate, finite, min/max, alignment delta.')
    p('Các lỗi shape, labels, finite và duration được báo ValueError; device/sensor lạ có thể gây KeyError vì RATES là mapping cố định. Cấu trúc signal thiếu hoặc đầu vào không phải mảng NumPy cũng có thể gây lỗi kiểu/thuộc tính. Hàm không kiểm chứng toàn bộ ý nghĩa sinh lý của giá trị hữu hạn; min/max không đủ phát hiện nhiễu chuyển động, clipping cảm biến hay sai calibration.')
    h3('5.4. inspect_dataset(root, output)'); p('Duyệt đúng SUBJECTS đã khai báo, tải mỗi người một lần, gọi inspect_subject, ghi SHA256 raw vào item và giải phóng biến data. Báo cáo được lưu tăng dần, status từ running sang completed; khi lỗi, ghi failed và repr(error), rồi ném lại. finally luôn ghi ended_at và báo cáo, nên file inspection tồn tại không chứng minh đủ 15 người; phải xem status và độ dài subjects. scripts.inspect_dataset là entry point của hàm này.')
    h3('5.5. Đã hiểu cấu trúc đến đâu?'); p('Bằng chứng hiện có khá tốt về identity, shape, rate, duration, finite và phân bố nhãn. Thiếu một báo cáo toàn diện về thống kê phân vị, phân bố theo người/thời đoạn, duplicate tín hiệu, outlier có cơ sở sinh lý và chất lượng tín hiệu toàn bộ. audit_preprocessing bổ sung cửa sổ phẳng và ba trích đoạn S2, không thay thế kiểm tra đầy đủ. Không có bằng chứng raw đang thiếu giá trị: code chặn NaN/Inf và báo cáo lịch sử ghi finite; chưa có kiểm tra raw mới trong lần này.')
    ending('Ví dụ minh họa: một mảng [320,3] ở 32 Hz tương ứng 10 giây ACC, gồm 960 số. Cùng 10 giây BVP có shape [640,1], EDA [40,1]. Sau đồng bộ 32 Hz, chúng ghép thành [320,5]. Đây là ví dụ số nhỏ, không phải trích đoạn raw mới.',
      'Đọc dữ liệu phải gắn shape với rate, đơn vị, subject và nhãn. Inspection xác nhận bất biến cấu trúc; đánh giá chất lượng sinh lý cần thêm tiêu chí và bằng chứng.',
      ['Vì sao len(ACC) khác len(EDA) chưa chứng minh dữ liệu mất đồng bộ?','inspection.json có status=failed nhưng có vài subject thì được dùng như báo cáo hoàn chỉnh không?','Vì sao không được gọi min/max là kiểm tra outlier đầy đủ?'])

    chapter(6,'Tiền xử lý dữ liệu','Giải thích từng biến đổi từ raw đến cache; hiểu biên nhãn, cửa sổ, scaler, split và cache invalidation.',[
      'Resampling đặt các cảm biến trên cùng trục thời gian. Downsampling giảm số mẫu; upsampling tăng số vị trí biểu diễn nhưng không tạo thêm thông tin vật lý đã đo. Aliasing xảy ra khi thành phần tần số cao bị biểu diễn sai sau giảm sampling rate.',
      'Cửa sổ là đoạn liên tiếp dùng làm một mẫu học. Stride là khoảng dịch điểm bắt đầu; overlap 50% khiến hai cửa sổ liền kề chia sẻ nửa thời gian. Chia subject trước khi fit scaler là ranh giới tránh truyền thống kê của người Test vào huấn luyện.'])
    h2('C. Liên hệ codebase'); source(('src/data/resampling.py','resample_signal'),('src/data/resampling.py','align_labels'),('src/data/windowing.py','make_windows'),('src/data/preprocessing.py','prepare_subject'),('src/data/normalization.py','ChannelScaler'),('src/data/splits.py','create_manifest'))
    h2('D. Phân tích hoạt động'); h3('6.1. Lấy mẫu lại theo thời gian')
    p('resample_signal nhận signal [T,C], source_rate, target_rate và target_length. Đầu tiên đổi float32, yêu cầu finite và hai chiều, rồi so thời lượng với dung sai 1/source_rate + 1/target_rate. Không âm thầm crop/pad khi lệch. ACC 32→32 giữ nguyên mẫu; BVP 64→32 dùng scipy.signal.resample_poly theo tỉ lệ được rút gọn bằng gcd: up=1, down=2. Polyphase là cách thực thi lọc lấy mẫu lại hiệu quả bằng nhiều pha; bộ lọc trong resample_poly giúp hạn chế aliasing trước giảm mẫu. Code không tự khai báo cutoff hay thiết kế bộ lọc sinh lý riêng.')
    p('EDA 4→32 dùng np.interp theo từng kênh tại times=k/32 và source_times=j/4. Nội suy tuyến tính nối hai mẫu bằng đường thẳng: x(t)=x₀+(x₁−x₀)(t−t₀)/(t₁−t₀). Khi times vượt mốc nguồn cuối nhưng còn trong tổng thời lượng, np.interp giữ endpoint cuối. Đây là chính sách đã ghi metadata, không phải thêm mẫu đo mới. Sau xử lý, số hàng phải đúng target_length hoặc ValueError; output luôn float32.')
    h3('6.2. Căn nhãn bằng khoảng thời gian')
    p('align_labels tìm các đoạn nhãn không đổi [start,end) trên timeline 700 Hz. Chỉ nhãn gốc 1/2/3 được ánh xạ 0/1/2. Với đoạn hợp lệ, lo=ceil(start×target_rate/source_rate), hi=floor(end×target_rate/source_rate); chỉ output[lo:hi] được gán. Timeline đích ban đầu toàn −1. Cách chọn này chỉ cho một khoảng mẫu đích nằm trọn trong trạng thái gốc được giữ; đoạn rất ngắn không hợp lệ không bị mất chỉ vì chọn một điểm gần nhất.')
    excerpt('src/data/resampling.py',27,39); fig('alignment','Minh họa chính sách biên từ test_resampling; không phải dữ liệu WESAD mới.')
    h3('6.3. Cửa sổ neo trong từng vùng nhãn')
    p('make_windows nhận tín hiệu [T,C] và nhãn [T]. size=int(rate×window_seconds)=960; stride=480. boundaries tách khi nhãn đổi. Các vùng nhãn âm bị bỏ qua; vùng hợp lệ ngắn hơn size được đếm short_regions; vòng range(lo, hi−size+1, stride) chỉ giữ cửa sổ đủ dài trong cùng trạng thái. Không bỏ phiếu majority label cho một cửa sổ lẫn nhãn. Mỗi lát [size,C] được transpose thành [C,size], sau đó stack thành [N,C,size].')
    p('Rows có subject_id, window_id=Sx_start_end, start_time/end_time theo giây, original_label và label. Không có cửa sổ nào thì ValueError. Một vòng khác chỉ kiểm tra các ứng viên trên lưới toàn cục, đếm invalid_region/transition; đây là audit riêng. Với S2, kept=137, global_candidates=404, invalid=269. 137+269 không bắt buộc bằng 404 vì lưới neo giữ lại và lưới audit khác nhau.')
    h3('6.4. Cache có hai lớp định danh')
    p('cache_path lấy 16 ký tự đầu SHA256 của canonical data config để chọn thư mục, hiện là c369cd27d24abb09. prepare_subject dùng cache_key đầy đủ từ CACHE_VERSION + data config + raw_sha256 để kiểm tra nội dung mỗi người. Meta hợp lệ và từng file trong files tồn tại/khớp hash thì tái sử dụng; nếu không, đọc raw, kiểm tra, resample, căn nhãn và windowing. Metadata commit sau cùng để cache bị ngắt giữa chừng không được coi hoàn chỉnh.')
    p('Mảng lưu bằng tệp .npy tạm rồi os.replace; CSV được ghi cùng rows, metadata chứa shape/distribution/inspection/hashes. SHA256 là hàm băm nội dung để phát hiện thay đổi, không phải phép chuẩn hóa tín hiệu hay mã hóa. Version chuỗi phải được cập nhật có kiểm soát khi thuật toán thay đổi; cache_key chưa tự chứa hash source của resampling/windowing. Vì vậy đổi logic mà quên đổi CACHE_VERSION có thể tái sử dụng cache cũ. Đây là rủi ro thiết kế, không có bằng chứng cache hiện tại sai.')
    h3('6.5. Chuẩn hóa Train-only và weighting')
    p('ChannelScaler.fit yêu cầu Dataset chưa có scaler. Duyệt subject và từng block 64 windows, đổi float64 rồi chuyển [n,C,L] thành [C,n×L]. Mỗi block tính mean và tổng bình phương sai lệch. Khi gộp hai block A/B: δ=μB−μA; μ=μA+δ nB/(nA+nB); M₂=M₂A+M₂B+δ²nA nB/(nA+nB). Đây là cách gộp moment ổn định số hơn lấy tổng x² trừ bình phương tổng trên số lớn.')
    p('std=sqrt(M₂/count), ddof=0; mean/std lưu float32; std<1e−8 thay bằng 1. transform tính z=(x−μ)/σ theo từng kênh bằng broadcasting μ[:,None]. Fit trên mọi timestep của windows Train, kể cả đoạn chồng lấp, nên một thời điểm có thể góp trọng số nhiều lần. Đây là chính sách được ghi normalization.json, không phải tính trên các mẫu thời gian duy nhất. Mỗi fold có scaler khác, cache nền không bị sửa. Nếu Dataset Train rỗng, fit hiện chưa có nhánh thông báo lỗi rõ; phạm vi chính thức có dữ liệu.')
    h3('6.6. Split và chất lượng dữ liệu')
    p('splits.py cố định 15 ID, chia nhóm bằng random.Random(42).shuffle và quay vòng vai trò 9/3/3. Split không thao tác cắt lại mảng tín hiệu; Dataset chọn subject tương ứng sau khi cache được tạo. Chuẩn hóa sau khi xác định Train, không trước chia người. Chi tiết manifest nằm ở Chương 10.')
    p('Đã triển khai: finite/shape/duration, resampling chống aliasing khi giảm tần số, căn nhãn bảo thủ, region-local windows, cache integrity và train-only scaler. Chưa có xử lý tự động nhiễu chuyển động, phân rã EDA, clipping sinh lý hoặc lọc outlier toàn diện. Việc thiếu kỹ thuật nâng cao không tự động là bug; cần xác định vấn đề dữ liệu trước khi đổi preprocessing để giữ so sánh công bằng.')
    ending('Ví dụ minh họa: vùng một nhãn dài 70 giây, window 30 và stride 15 giây giữ các điểm bắt đầu 0,15,30: ba cửa sổ. Phần đuôi 10 giây không đủ tạo cửa sổ mới. Với μ=10, σ=2, giá trị 14 đổi thành z=2; Validation cũng dùng μ/σ Train ấy, không tự fit lại.',
      'Tiền xử lý hiện tại có quy tắc rõ về thời gian, biên nhãn và provenance. Cần đọc riêng thuật toán đã làm với audit chất lượng còn giới hạn; không cộng lẫn hai lưới windowing.',
      ['Nếu EDA từ 4 lên 32 Hz, thông tin đo có tăng tám lần không?','Vì sao dùng ceil cho lo và floor cho hi?','Đổi windowing.py nhưng giữ CACHE_VERSION có rủi ro gì?','Mean/std của Fold 1 và Fold 2 có cần giống nhau không?'])

    chapter(7,'PyTorch Dataset và DataLoader','Theo một window từ cache đến model, hiểu bộ nhớ, chỉ số mẫu và thứ tự các chiều.',[
      'Dataset định nghĩa số mẫu và cách lấy một mẫu theo index; DataLoader ghép nhiều mẫu thành mini-batch, có thể xáo trộn thứ tự và dùng worker. Epoch là một lượt duyệt tập Train; batch cuối có thể nhỏ hơn batch_size vì code không đặt drop_last=True.',
      'Memory mapping cho phép truy cập vùng cần dùng của tệp mảng mà không bắt buộc nạp toàn bộ vào RAM. Nó vẫn dùng bộ nhớ trang của hệ điều hành và không làm mọi thao tác miễn phí: code còn sao chép một window và fit scaler theo block.'])
    h2('C. Liên hệ codebase'); source(('src/data/dataset.py','WindowDataset'),('src/data/normalization.py','ChannelScaler'),('src/training/trainer.py','train_fold'))
    h2('D. Phân tích hoạt động'); p('WindowDataset.__init__(cache, subjects, scaler=None) lưu danh sách subjects, mở windows.npy với mmap_mode="r", đọc cache_key từ metadata và toàn bộ rows CSV. Số rows phải bằng số windows, nếu không ValueError. indices chứa cặp (subject, offset), còn labels là NumPy int64 ghép từ các rows. Nhờ indices, index toàn Dataset vẫn truy xuất được subject và window gốc.')
    p('__getitem__(index) lấy (subject,offset), tạo np.array(...,copy=True), chuẩn hóa nếu có scaler rồi trả (torch.from_numpy(x), int(label), index). Copy giúp không ghi đè memmap chỉ đọc. torch.from_numpy chia sẻ vùng nhớ của bản window mới; DataLoader mặc định collate thành x [B,C,L], y [B] kiểu int64 và index [B]. Index được evaluator mang theo để gắn xác suất lại với đúng window_id khi export_test.')
    p('Trainer tạo ba Dataset chưa chuẩn hóa, fit ChannelScaler trên train, rồi gắn cùng scaler vào Train/Validation/Test. DataLoader Train để đánh giá đặt shuffle=False; train_loader cập nhật weights đặt shuffle=True. Validation/Test không shuffle. Tách hai loader Train giúp online loss lúc weights còn đổi khác với phép đánh giá sau epoch trên model cố định. num_workers=0 giảm phức tạp multiprocessing trên cấu hình hiện tại; không nên suy ra đã benchmark workers khác.')
    table('Một mẫu và một batch qua từng bước',['Vị trí','Shape / kiểu','Ý nghĩa'],[
      ('Cache của S2','[137,5,960], float32 theo metadata','Tất cả windows của một người'),('Lấy window offset i','[5,960]','Mỗi hàng là một kênh xuyên thời gian'),('Sau transform','[5,960], float32','Trừ mean/chia std Train theo từng hàng'),('Dataset trả về','(Tensor[5,960], int, index)','Nhãn là 0/1/2; index là định danh vị trí trong Dataset'),('DataLoader batch 32','x=[32,5,960]; y=[32]; index=[32]','32 cửa sổ, không phải 32 timesteps'),('Sau model','logits=[32,3]','Một bộ ba logits cho mỗi cửa sổ')],[4,6,7])
    p('Một window float32 cần 5×960×4=19.200 byte, khoảng 18,75 KiB; một batch 32 chứa riêng x khoảng 0,586 MiB. Đây là tính toán minh họa từ shape, chưa gồm gradients, activations, optimizer, copies và cache hệ điều hành. Pipeline xử lý raw từng người và fit theo block để hạn chế RAM; không có số benchmark RAM mới trong lần này.')
    ending('Ví dụ tổng hợp trong test_dataset: mỗi người giả lập có 6 windows [5,32]. Ghép S2 và S3 tạo len=12; index 7 thuộc S3 offset 1. Test kiểm tra x.shape==(5,32), y==1, i==7 và arrays["S2"] là np.memmap. Đây là fixture logic, không phải cửa sổ WESAD thật dài 30 giây.',
      'Dataset giữ hợp đồng mẫu và danh tính; DataLoader giữ hợp đồng batch. Cùng cache có thể tái sử dụng giữa models mà scaler vẫn độc lập theo fold.',
      ['Vì sao __getitem__ phải copy trước transform?','Nếu shuffle=True, evaluator làm sao gắn lại dự đoán đúng window?','RAM batch có phải toàn bộ RAM mà training cần không?'])

    chapter(8,'Các mô hình Deep Learning','Đọc từng lớp CNN và GRU, theo dõi shapes và phân biệt kiến trúc thật với proposal.',[
      'Conv1d dùng các kernel có chiều thời gian và kết hợp mọi input channel. Output channels là số bộ lọc học được; chúng không còn đồng nghĩa với các cảm biến gốc. Logits là điểm số chưa chuẩn hóa; CrossEntropyLoss đã tích hợp log-softmax nên không thêm softmax trước loss.',
      'GRU duy trì hidden state h qua thời gian. Các cổng điều khiển bao nhiêu thông tin cũ được giữ lại và thông tin mới được cập nhật. Với một lớp một chiều, trạng thái cuối có thể đại diện toàn chuỗi để phân loại, nhưng chất lượng biểu diễn vẫn phải được đánh giá thực nghiệm.'])
    h2('C. Liên hệ codebase'); source(('src/models/cnn.py','CNN1D'),('src/models/gru.py','GRUClassifier'),('src/models/__init__.py','build_model'),'src/models/cnn_gru.py','tests/test_model.py','tests/test_gru.py')
    h2('D. Phân tích hoạt động'); h3('8.1. CNN ba khối đang được dùng')
    table('Shapes của CNN1D cho B cửa sổ',['Tầng','Tham số chính','Đầu ra'],[
      ('Đầu vào','5 kênh, 960 timesteps','[B,5,960]'),('Khối 1','Conv 5→32, k=7,p=3; BatchNorm; ReLU; MaxPool k=2','[B,32,480]'),('Khối 2','Conv 32→64, k=5,p=2; BatchNorm; ReLU; MaxPool k=2','[B,64,240]'),('Khối 3','Conv 64→128, k=3,p=1; BatchNorm; ReLU; không MaxPool','[B,128,240]'),('Gộp và trải phẳng','AdaptiveAvgPool1d(1); Flatten','[B,128]'),('Classifier','Linear 128→64; ReLU; Dropout(.3); Linear 64→3','[B,3]')],[3.8,8.3,4.9])
    p('Với dilation d, kernel k, padding p và stride s, L_out=floor((L_in+2p−d(k−1)−1)/s+1). Conv dùng stride=1,d=1 và padding như trên nên giữ chiều dài. MaxPool1d(2) mặc định stride=2, nên 960→480→240. BatchNorm1d chuẩn hóa activation theo channel khi train và dùng thống kê chạy khi eval; nó là một thành phần khác với ChannelScaler tiền xử lý Train-only. ReLU là max(0,x). Global average pooling lấy trung bình trên thời gian, tránh classifier phải nhận 128×240 features. Dropout chỉ hoạt động ở train, đặt ngẫu nhiên một phần activation về 0 với scaling tương ứng.')
    p('CNN hiện có 45.059 tham số trainable; con số được assertions test_model và metadata E1 hỗ trợ, không được đo lại bằng khởi tạo model trong nhiệm vụ. Trình tự model được giữ nguyên khi chuyển sang factory để E1 state_dict vẫn tương thích. Không có một cờ YAML trong CNN1D để chọn hai khối: kiến trúc đang hardcode ba Conv1d trong nn.Sequential.')
    h3('8.2. Phân biệt CNN hai khối theo proposal')
    table('Ba trạng thái không được gộp làm một',['Thiết kế','Bằng chứng','Cách trình bày đúng'],[
      ('CNN ba khối E1','cnn.py; snapshot E1; metadata architecture; registry','Đã triển khai, có tests, đã thực thi và E1 chính thức finalized'),('CNN hai khối theo proposal','Yêu cầu người dùng nhắc đến; không có đặc tả đầy đủ trong source/config văn bản hiện có','Mục tiêu riêng, chưa xác minh filters/kernel/pooling và chưa có kết quả gắn với triển khai hai khối'),('CNN-GRU','cnn_gru.py chỉ docstring; YAML status=planned','Chưa triển khai; không suy ra tồn tại từ tên tệp hoặc tên experiment')],[4.4,6,6.6])
    p('Nếu triển khai CNN hai khối về sau, phải gắn một thiết kế/GROUP_ID mới, ghi đầy đủ kiến trúc và shapes, giữ E1 ba khối làm lịch sử. Việc xóa một khối có thể đổi kích thước features và số tham số; không được chỉ thay mô tả trong báo cáo rồi dùng kết quả E1 cũ.')
    h3('8.3. GRU hiện đã có triển khai')
    p('GRUClassifier nhận [B,5,960], transpose(1,2).contiguous() thành [B,960,5] vì batch_first=True. nn.GRU(input_channels,hidden_size) mặc định một lớp, một chiều; output theo từng timestep bị bỏ qua và hidden cuối được lấy hidden[-1] với shape [B,64]. Classifier Linear 64→64, ReLU, Dropout(.3), Linear 64→3 trả logits. Metadata và README E2 ghi 17.987 tham số trainable.')
    p('Công thức theo quy ước PyTorch, viết ở mức khái niệm: rₜ=σ(W_ir xₜ+b_ir+W_hr hₜ₋₁+b_hr); zₜ=σ(W_iz xₜ+b_iz+W_hz hₜ₋₁+b_hz); nₜ=tanh(W_in xₜ+b_in+rₜ⊙(W_hn hₜ₋₁+b_hn)); hₜ=(1−zₜ)⊙nₜ+zₜ⊙hₜ₋₁. Reset gate r điều tiết phần trạng thái cũ đi vào candidate; update gate z điều tiết giữ trạng thái cũ. Code dùng nn.GRU, không viết tay các cổng. Dropout nằm ở classifier vì dropout của GRU nhiều lớp không áp dụng giữa recurrent layers khi chỉ có một lớp.')
    fig('tensors','Đường đi tensor qua hai mô hình đã triển khai.')
    ending('Ví dụ minh họa: với B=2, GRU nhận [2,5,960], chuyển [2,960,5], hidden có [1,2,64]. hidden[-1] lấy chiều lớp, còn cả hai samples vẫn tách biệt. Nhầm hidden[-1] với lấy sample cuối sẽ khiến giải thích sai dù cú pháp nhìn tương tự.',
      'CNN ba khối và GRU là hai triển khai thật. CNN hai khối của proposal và CNN-GRU phải được theo dõi như thiết kế tương lai riêng, không mượn kết quả E1/E2.',
      ['Tại sao pooling giảm chiều dài mà Conv giữ chiều dài trong CNN này?','BatchNorm có thay thế ChannelScaler không?','Vì sao GRU dùng transpose nhưng CNN không cần?','Dropout .3 của E2 nằm trong GRU hay classifier?'])

    chapter(9,'Pipeline huấn luyện','Theo một mini-batch từ forward đến cập nhật weights; hiểu weighted loss, selection, early stopping và resume.',[
      'Huấn luyện thay đổi tham số qua gradient của loss; validation đo mô hình hiện tại để chọn checkpoint; testing đánh giá sau lựa chọn. model.train()/eval() điều khiển Dropout/BatchNorm, còn bật/tắt gradient là một cơ chế khác.',
      'Seed cố định giúp kiểm soát khởi tạo, xáo trộn batch và dropout trong cùng môi trường. Nó không bảo đảm mọi bản PyTorch, phần cứng và nền tảng tạo kết quả giống từng bit.'])
    h2('C. Liên hệ codebase'); source(('src/training/trainer.py','train_fold'),('src/training/optimizer.py','class_weights'),('src/training/callbacks.py','SelectionState'),('src/training/checkpoint.py','save_checkpoint'),('src/utils/reproducibility.py','seed_everything'))
    h2('D. Phân tích hoạt động'); h3('9.1. Khởi tạo một fold')
    p('train_fold kiểm tra completion trước khi chạy. Một fold completed có hashes đúng sẽ được skip khi resume, hoặc bị từ chối nếu không yêu cầu resume. Fold mới khởi tạo logger, run ID, attempt ID, metadata và so khớp config/split/seed. Sau đặt RNG và device, nó tạo Dataset, fit Train scaler, DataLoaders, model mới, Adam, class weights và SelectionState. Không truyền weights từ fold trước sang fold sau.')
    p('Class weights: w_c=N_train/(3n_c). Nếu một lớp không có mẫu Train thì ValueError. Ví dụ minh họa counts=[6,3,3], N=12 cho weights=[2/3,4/3,4/3]. Với logits z, p_c=exp(z_c)/Σ exp(z_j), loss trung bình có trọng số là L=−Σᵢ w_yᵢ log pᵢ,yᵢ / Σᵢ w_yᵢ. Denominator là tổng trọng số của nhãn batch, không đơn giản là số samples.')
    h3('9.2. Một mini-batch đi qua những dòng nào?')
    bullets(['Đưa x/y lên device; optimizer.zero_grad(set_to_none=True) xóa gradient của bước trước.',
      'Forward model(x) tạo logits [B,3]; criterion(logits,y) tính weighted cross entropy và chặn loss NaN/Inf.',
      'loss.backward() tính đạo hàm ngược qua mạng vào .grad; gradient cho biết độ nhạy cục bộ của loss với tham số.',
      'clip_grad_norm_(...,max_norm=1.0,error_if_nonfinite=True) giới hạn norm tổng; norm ghi vào log là giá trị trước clipping.',
      'optimizer.step() dùng Adam cập nhật tham số; global_step tăng; ghi batch loss, lr, norm, thời lượng và identity.'])
    p('Adam lưu moment bậc một/hai của gradients để điều chỉnh bước cập nhật cho từng tham số; weight_decay trong torch.optim.Adam là penalty L2 theo API đang dùng, không nên gọi nó là AdamW. Code không có scheduler. Train online loss cộng numerator=loss_batch×sum(weights[y]), denominator=sum(weights[y]) để toàn epoch không lệch vì batch cuối nhỏ hoặc thành phần lớp khác nhau.')
    h3('9.3. Sau epoch và chọn best')
    p('Sau batch cuối, evaluate chạy trên Train không shuffle và Validation bằng inference_mode với model.eval(). Các scores Train sau epoch vì vậy đo một model cố định, khác online loss vừa quan sát trên nhiều trạng thái weights. SelectionState ưu tiên macro_f1 lớn hơn best_score trong tolerance 1e−12; nếu hòa thì val_loss thấp hơn. Khi better, best_state được clone về CPU, gồm cả state_dict buffers như BatchNorm.')
    p('Early stopping có anchor riêng: chỉ score>anchor+min_delta mới reset bad_epochs. Một cải thiện đủ nhỏ vẫn có thể cập nhật best nhưng không reset patience; hòa Macro-F1 với loss tốt hơn cũng có thể lưu best mà patience vẫn tăng. Khi bad_epochs>=15, dừng sau commit epoch. Đây là khác biệt chủ ý được kiểm tra trong test_validation_selection_and_patience.')
    h3('9.4. Checkpoint và hồi phục')
    p('save_checkpoint ghi tệp tạm, flush, fsync rồi os.replace. best.pt đại diện model được chọn; last.pt là epoch đã commit để resume. State chứa model/optimizer, epoch/global_step, early_stopping, history, best_model, RNG, effective_config, cache_keys và manifest_checksum. scheduler=None phản ánh không có scheduler. Atomic replace giảm nguy cơ đọc một checkpoint viết dở; nó không tự sửa mọi lỗi đĩa hoặc dòng CSV bị cắt giữa chừng.')
    p('Resume nạp last.pt, kiểm tra identity/config/cache, khôi phục model/optimizer/selection/history và RNG; epoch_start=epoch+1. best.pt được dựng lại từ best_model trong last để một best viết ở epoch chưa commit không lấn quyền. recover_epoch_logs ghi bù idempotent. Nếu gián đoạn giữa epoch, epoch ấy được chạy lại; attempt ID giúp audit tách các iterations mồ côi. Không hứa tiếp từ đúng mini-batch đang dở.')
    h3('9.5. Test và kết thúc')
    p('Sau khi selection kết thúc, nạp best.pt rồi mới evaluate Test. export_test ghi predictions, class report, per-subject metrics và confusion matrix; metadata chuyển completed. completion.json ghi hashes của file trong fold sau đóng tracker. Outer group còn tổng hợp và tạo hình; lỗi hậu xử lý có thể làm group failed dù các folds đã completed. Cần xem đúng tầng lifecycle khi debug.')
    p('load_checkpoint của training dùng weights_only=False cho checkpoint cục bộ tin cậy; hậu kiểm E1 có safe_load_checkpoint dùng weights_only=True và allowlist NumPy cố định. Đây là hai code path khác nhau. Trong nhiệm vụ chỉ đọc source và báo cáo đã lưu, không deserialize cả hai loại checkpoint.')
    ending('Ví dụ từ unit test selection: patience=2, min_delta=.001. Epoch 1 score=.5 lưu best và reset; epoch 2 score=.5 nhưng loss giảm vẫn lưu best, bad_epochs=1; epoch 3 score=.5005 tiếp tục là best nhưng chưa vượt anchor+.001, nên bad_epochs=2 và dừng. Số này minh họa logic test, không phải training E1.',
      'Độ tin cậy đến từ tách Train/Validation/Test, công thức loss nhất quán và checkpoint có identity. best selection và patience là hai tiêu chí khác nhau.',
      ['Vì sao không lấy mean của các batch mean loss một cách vô điều kiện?','Tại sao best checkpoint có thể được cập nhật ngay trong epoch dừng sớm?','Resume giữa epoch bảo toàn iterations cũ như thế nào mà không đếm chúng hai lần?'])

    chapter(10,'Cross-validation và thiết kế thực nghiệm','Đọc manifest cụ thể, hiểu quay vòng vai trò và những điều kiện để so sánh models công bằng.',[
      'Cross-validation thay đổi vai trò các phần dữ liệu để đánh giá trên nhiều tập giữ lại. Grouped splitting giữ mọi cửa sổ của một subject trong cùng một vai trò ở mỗi fold, tránh mô hình khai thác dấu vết cá nhân hoặc overlap để đoán Test.',
      'OOF (out-of-fold) là dự đoán của từng mẫu khi mẫu ấy ở Test của fold tương ứng. Nó không phải output của một model duy nhất huấn luyện trên toàn bộ 15 người.'])
