    h2('D. Phân tích hoạt động'); split=json.loads(C['splits/grouped_5fold_seed42.json'])
    table('Manifest thật: 9 Train / 3 Validation / 3 Test',['Fold','Train','Validation','Test'],[(f['fold_id'],', '.join(f['train']),', '.join(f['validation']),', '.join(f['test'])) for f in split['folds']],[1.2,8.2,3.8,3.8])
    p('Năm nhóm sau shuffle là G1=[S10,S16,S9], G2=[S8,S17,S15], G3=[S7,S4,S11], G4=[S5,S6,S14], G5=[S2,S3,S13]. Fold k lấy Gk làm Test, nhóm kế tiếp theo vòng làm Validation, ba nhóm còn lại làm Train. Mỗi người là Train ba lần, Validation một lần, Test một lần. Đây là grouped 5-fold 9/3/3, không phải LOSO và cũng không phải nested cross-validation đầy đủ để dò nhiều hyperparameters.')
    p('load_manifest kiểm tra SHA256 canonical JSON với tệp .sha256 rồi validate_manifest so nguyên manifest với thuật toán tạo lại và kiểm tra coverage/role sizes. Canonical hash dùng sort_keys, UTF-8, không khoảng trắng thừa; khác hash byte của một JSON được pretty-print. ensure_manifest từ chối ghi đè manifest khác seed hoặc checksum mồ côi. Chia người được đóng băng ở seed 42; đổi training seed không tạo split mới.')
    p('Trong lần biên soạn đã kiểm tra mới checksum canonical và các vai trò rời nhau từ JSON. Với bốn groups, CSV OOF có 2.136 khóa (seed,subject,window_id) duy nhất, đủ 15 subject và fold đúng Test manifest; xác suất hữu hạn/không âm/tổng gần 1 và argmax khớp nhãn dự đoán. Đây là kiểm tra văn bản, không xác nhận lại inference từ weights.')
    table('Điều kiện so sánh công bằng',['Yếu tố','Hiện trạng / điều cần giữ'],[
      ('Dữ liệu và split','E1/E2 dùng cùng data config, cache key và split seed. Scaler và class weights fit riêng trên đúng Train.'),('Selection','Validation Macro-F1 và tie-break loss thống nhất; Test chỉ báo cáo sau selection.'),('Ngân sách','E2 hiện một cấu hình/seed; CNN có lượt thử WD riêng. Chưa có ngân sách tuning cân bằng và nhiều seeds để kết luận tổng quát.'),('Kiến trúc','45.059 tham số CNN và 17.987 GRU khác nhau; cùng hyperparameters không có nghĩa cùng năng lực hoặc chi phí tính toán.'),('Môi trường','So sánh ngày 17/11 dùng CNN đối chứng ngày 15/11 trên cùng môi trường; E1 canonical khác máy/phiên bản được giữ riêng.'),('Tiêu chí báo cáo','Metric chính hiện hành là mean Macro-F1 theo người; giữ cùng cách tổng hợp khi so sánh.')],[3.5,13.5])
    ending('Ví dụ minh họa: Fold 1 giữ S10/S16/S9 làm Test. Một window của S10 không thể xuất hiện trong Train hay scaler của Fold 1, dù có thời điểm khác trong cùng bản ghi. Sang Fold khác S10 có thể nằm Train, vì model của fold ấy được khởi tạo lại và Test là nhóm khác.',
      'Manifest là hợp đồng khoa học dùng chung. Grouped protocol hạn chế subject leakage nhưng không tự giải quyết mọi thiên lệch nghiên cứu, đặc biệt việc lặp lựa chọn thiết kế sau khi xem Test.',
      ['Một subject được làm Train ba lần có vi phạm protocol không?','Vì sao mean/std giữa folds không phải độ ổn định giữa seeds?','Nếu CNN hai khối được thêm, cần giữ những phần nào để kết quả đối chiếu được?'])

