    table('Bao phủ từ toàn bộ 17 module test hiện tại',['Module','Nội dung','Ý nghĩa assertions / biên'],tests,[4.8,6.1,6.1])
    p('conftest.tiny_cache tạo 15 người giả, mỗi người 6 windows [5,32], nhãn luân phiên 0/1/2. synthetic_history tạo history schema cũ để thử plotting/importer, còn fake_wandb là mock SDK. Các tests có gọi train_fold nhưng chỉ trên dữ liệu giả; trong nhiệm vụ hiện tại không chạy pytest để tuân thủ phạm vi chỉ đọc và không tạo training artifacts. Kiểm tra mới chỉ dùng AST và văn bản CSV/JSON.')
    table('Lịch sử tests: không phải kết quả chạy mới',['Artifact JUnit','Thời điểm ghi trong XML','Pass / skip / lỗi'],[
      ('results/pytest-results.xml','07/11/2026, 23:11 +07','23 pass; 0 skip; 0 fail/error'),('results/tracking_upgrade/pytest-results.xml','08/11/2026, 15:15 +07','37 pass; 0 skip; 0 fail/error'),('results/tensorboard_upgrade/pytest-results.xml','08/11/2026, 21:41 +07','43 pass; 0 skip; 0 fail/error'),(R1+'/finalization_pytest.xml','09/11/2026, 11:20 +07','50 pass; 2 skip; 0 fail/error'),('experiments/e2_gru/checks/pytest.xml','17/11/2026, 14:52 +07','58 pass; 2 skip; 0 fail/error')],[8.1,4.3,4.6])
    p('Hai test bị skip là test_tracking_preserves_original_model_weights và test_historical_regression_unchanged vì thiếu group e1_seed42_20261107/snapshot cũ. Canonical group ngày 08/11 vẫn hiện diện; không gọi hai skip ấy là mất E1 chính thức. README gốc còn ghi 50 passed/2 skipped từ finalization; hồ sơ E2 mới hơn ghi 58/2. Phụ lục B liệt kê từng test function và điều nó kiểm tra.')
    p('Kiểm tra mới trong nhiệm vụ: AST parse cả 268 Python files, đọc 808 tệp văn bản trong phạm vi an toàn, kiểm checksum manifest, hash text snapshot, kiểm rows/metadata của 15 subject và tính lại pooled/subject metrics của bốn groups từ predictions. Chưa xác minh lại binary arrays, inference, event values, checkpoint weights hoặc độ bao phủ bằng công cụ coverage. Không dùng số tests đã pass để thay một báo cáo coverage chưa có.')
    ending('Ví dụ đọc assertion: prepare.assert_not_called() trong test_dry_run_never_preprocesses_or_trains kiểm tra một ranh giới tác động, không kiểm chất lượng tín hiệu. assert torch.equal(weights_reference,weights_resumed) trong test_resume kiểm sự hồi phục trên fixture và môi trường test, không chứng minh tái lập giữa mọi máy.',
      'Một test cần được đọc cùng fixture, assertion và thời điểm chạy. Mức bằng chứng phải ghi rõ: source test, XML lịch sử hay kiểm tra văn bản mới.',
      ['58 passed trong XML E2 có phải kết quả pytest mới ngày biên soạn không?','Một test dùng mock runner có chứng minh training trên raw thật không?','Vì sao two skipped không nên cộng vào số passed?'])

    chapter(14,'Trạng thái codebase theo subsystem','Đánh giá riêng mức triển khai, kiểm thử, thực thi và finalization bằng bằng chứng cụ thể.',[
      'Implemented nghĩa là có logic thực thi; tested nghĩa là có bằng chứng test trong phạm vi nêu rõ; executed nghĩa là có artifacts của một lượt chạy. Finalized là trạng thái hồ sơ được đóng băng. Planned/incomplete/unverified diễn tả những mức chưa đủ bằng chứng khác nhau, không tự thay bằng completed.',
      'Một subsystem có thể vừa implemented vừa còn giới hạn nghiên cứu. Không nên dùng một nhãn hoàn thành duy nhất cho mã thuật toán, chất lượng dữ liệu, reproducibility và kết quả khoa học.'])
