    chapter(16,'Lộ trình học và làm chủ codebase','Học theo các hợp đồng dữ liệu và bằng chứng, luyện giải thích thay vì học thuộc source.',[
      'Lộ trình hiệu quả đi từ bản đồ đến một lát cắt chạy xuyên hệ thống: YAML → window → batch → logits → predictions → summary. Sau đó quay lại ngoại lệ, resume và provenance.',
      'Các bài tập dưới đây là đề xuất học trong môi trường riêng về sau. Nhiệm vụ hiện tại không thực thi bài tập, không sinh synthetic training và không can thiệp dữ liệu nghiên cứu. Bài tập tính tay hoặc đọc source có thể làm ngay mà không thay đổi dự án.'])
    h2('C. Liên hệ codebase'); source('README.md','configs/default.yaml','tests/conftest.py','experiments/journal/README.md')
    h2('D. Phân tích hoạt động'); stages=[
      ('1. Bản đồ Python','README → scripts/run_grouped_cv → src/training/trainer','Biết module/package/import và cwd.','Vẽ chuỗi main→run→train_fold; giải thích ai gọi ai.','Kể lại được đường đi một lệnh mà không phải mở toàn bộ file cùng lúc.'),
      ('2. YAML và hợp nhất','configs/default.yaml → src/utils/config → experiments/e2_gru/config.yaml','Biết dict/list và copy sâu.','Tính tay effective training config của E2; hỏi danh sách được nối hay thay.','Theo được batch_size hoặc learning_rate tới DataLoader/Adam và giải thích guard.'),
      ('3. Hiểu WESAD','inspection.py → data/interim/inspection.json → metadata S2','Biết array shape, dtype, sampling rate.','Tính 194.528/32; giải thích vì sao BVP có số hàng gấp đôi.','Đọc được một signal record, không nhầm channels với subjects.'),
      ('4. Thống kê mô tả','inspection.py → audit_preprocessing.py → class_distribution.csv','Biết mean/std/percentile và tỷ lệ lớp.','Tính 1.150/2.136; phân biệt phân bố window với người.','Nêu được statistic nào hiện có, statistic nào cần bổ sung và mục đích của nó.'),
      ('5. Thiếu, trùng và ngoại lai','inspection.py → preprocessing_review/channel_checks.csv → test_aggregation','Biết finite, duplicate key và flat signal.','Phân loại 27 cặp phẳng; hỏi trùng ID khác trùng nội dung ra sao.','Không tự gọi mọi flat value là lỗi và đề xuất kiểm chứng có tiêu chí.'),
      ('6. Resampling/windowing','resampling.py → windowing.py → tests tương ứng','Biết Nyquist, interpolation và khoảng [a,b).','Tính tay ba cửa sổ từ vùng 70 giây; theo label interval cực ngắn.','Giải thích được vì sao không majority-vote qua biên và không cộng hai lưới đếm.'),
      ('7. Split/normalization','splits.py → manifest → normalization.py → tests','Biết z-score và grouped evaluation.','Liệt kê Train của Fold 1, tính μ/σ từ mảng nhỏ minh họa.','Chỉ ra chính xác nơi fit Train và cách Val/Test tái sử dụng thống kê.'),
      ('8. Dataset/batch','dataset.py → trainer DataLoaders → test_dataset','Biết __len__, __getitem__, tensor collation.','Theo index 7 trong fixture hai subject; viết shapes trước/sau collate.','Giải thích memmap/copy/scaler/index mà không nạp dữ liệu thật.'),
      ('9. CNN/GRU','cnn.py → gru.py → factory → test_model/test_gru','Biết Conv1d, pooling, hidden state và logits.','Tính 960→480→240; theo transpose GRU và hidden[-1].','Phân biệt ba khối thực tế với hai khối proposal và placeholder hybrid.'),
      ('10. Training/backprop','optimizer.py → callbacks.py → trainer → test_resume','Biết loss, gradients, optimizer state.','Tính class weights và loss denominator; theo một mini-batch.','Phân biệt online/eval loss, best selection/patience và epoch commit.'),
      ('11. Cross-validation','manifest → run_grouped_cv → aggregation.py','Biết Train/Val/Test và OOF.','Đếm mỗi subject xuất hiện theo vai trò 3/1/1.','Giải thích vì sao giao thức không là LOSO và vì sao Test không chọn checkpoint.'),
      ('12. Metrics','metrics.py → evaluator.py → summary/OOF CSV','Biết TP/FP/FN và trung bình phi tuyến.','Tính recall stress=331/640 từ E1; đối chiếu ba cách tổng hợp.','Báo cáo score luôn kèm level, seed và GROUP_ID.'),
      ('13. Logs/checkpoints','logging.py → tensorboard_tracker.py → checkpoint.py','Biết state_dict, RNG và append-only logs.','Theo attempt ID ở ví dụ resume; phân biệt last với best.','Mô tả được dữ liệu đã commit và các trục TensorBoard mà không mở events.'),
      ('14. Quản lý experiment','runner → completion/manifest → registry → journal README','Biết hash, identity và lifecycle.','Tạo bảng giấy cho một giả thuyết mới, để trống kết quả chưa chạy.','Không nhầm planned/completed/finalized hoặc dùng nhóm cũ làm nơi tuning.'),
      ('15. Tái lập nghiên cứu','source_checksums → system.json → XML → verification','Biết môi trường/pins và mức bằng chứng.','Lập danh sách tối thiểu tái lập; ghi giới hạn raw/binary chưa xác minh.','Giải thích được một kết quả đến nguồn code/data/protocol và nói rõ điều chưa biết.')]
    for title,files,prior,exercise,criterion in stages:
        h3(title); p('Mục tiêu và file đọc theo thứ tự: '+files+'.'); p('Nền tảng cần nắm: '+prior+' Bài tập / câu hỏi: '+exercise+' Tiêu chí đã hiểu: '+criterion)
    ending('Ví dụ tự kiểm tra cuối lộ trình: chọn một dòng predictions.csv, xác định fold/subject/window_id, theo window metadata về config 32 Hz/30 giây, tìm Test subjects trong manifest, rồi giải thích logits→softmax→argmax→metrics. Nếu không chỉ ra được một mắt xích, quay lại đúng module ấy thay vì đọc lại toàn repo.',
      'Năng lực làm chủ là tự đặt câu hỏi, tìm bằng chứng và dự đoán tác động thay đổi trước khi chạy. Không cần nhớ cú pháp của mọi hàm.',
      ['Bạn có thể giải thích đường đi một window trong ba phút mà không dùng từ “pipeline” một cách chung chung không?','Bạn biết tìm file nào khi score trong README khác summary không?','Bạn có thể mô tả thay đổi an toàn nào cần group mới và bằng chứng gì để xác nhận nó?'])

    chapter(17,'Roadmap nghiên cứu tiếp theo','Đề xuất trình tự dựa trên trạng thái mới nhất, có tiêu chí hoàn tất; không triển khai roadmap trong nhiệm vụ.',[
      'Roadmap nghiên cứu là chuỗi quyết định có đầu ra kiểm chứng, không phải danh sách kỹ thuật phải thêm cho đủ. Đóng băng dữ liệu/giao thức giúp phân biệt tác động kiến trúc với tác động tiền xử lý.',
      'Khi phát hiện source mới hơn nhật ký, cập nhật kế hoạch theo bằng chứng thật: E2 đã có lượt đầu; bước tiếp theo không nên ghi lại như thể chưa có GRU. Một thiết kế mới cần budget và criteria trước khi nhìn Test.'])
    h2('C. Liên hệ codebase'); source('src/models/cnn_gru.py','experiments/e3_cnn_gru/config.yaml','experiments/ablation/no_eda.yaml','experiments/e2_gru/README.md',R2+'/cnn_gru_comparison.md')
    h2('D. Phân tích hoạt động'); table('Roadmap đề xuất và tiêu chí kiểm chứng',['Giai đoạn','Công việc đề xuất','Điều kiện hoàn tất / phụ thuộc'],[
      ('1. Hiểu WESAD','Đối chiếu metadata với đặc tả chính thức, units và giao thức nhãn.','Tài liệu data dictionary theo sensor/subject/time; mọi đơn vị chưa xác minh được ghi rõ.'),('2. Data Understanding / Quality','Bổ sung thống kê phân vị, missing/flat/clipping, duplicate nội dung theo subject.','Báo cáo tiêu chí và kết quả, không gộp overlap thành quan sát độc lập.'),('3. EDA / Signal quality','Mở rộng kiểm tra waveform beyond ba đoạn S2 khi được phép nghiên cứu mới.','Quy tắc chọn đoạn rõ, số lượng phủ subject/lớp; nêu ảnh hưởng giả thuyết xử lý nhiễu.'),('4. Đặc tả preprocessing','Viết rõ rates, anti-aliasing, biên nhãn, endpoint hold, window anchors, scaler weighting.','Đặc tả đối chiếu code/tests; mọi thay đổi có version và cache mới.'),('5. Xác minh processed dataset','Trong nhiệm vụ nghiên cứu riêng, kiểm tra arrays/hashes và tái tạo có kiểm soát.','Đủ 15 người, shape/labels/counts và signal checks; tách kiểm tra mới khỏi audit lịch sử.'),('6. Đóng băng protocol','Chốt splits, main metric subject-level, training seeds và ngân sách tuning.','Manifest/checksum/source/config lưu riêng; tiêu chí chọn trước khi Test.'),('7. CNN hai khối proposal','Thu thập đặc tả còn thiếu, triển khai kiến trúc độc lập nếu đó là mục tiêu đã thống nhất.','Shape/parameter/forward/backward tests; group mới; không gán E1 ba khối thành kết quả mới.'),('8. GRU giai đoạn tiếp','Dùng E2 hiện tại làm lượt đầu; lập kế hoạch nhiều seeds hoặc tuning cân bằng.','Cùng protocol/data/selection; báo cáo biến thiên đúng cấp, không sửa thiết kế vì Test thấp.'),('9. CNN-GRU','Triển khai module, factory/config validation và tests rồi chạy theo kế hoạch.','Không còn placeholder; đầy đủ folds, OOF, logs/verification; budget công bằng.'),('10. Sensor ablation','Làm rõ zero-after-scaling giữ 5 kênh hay loại sensor; theo thiết kế đã chọn.','Config và implementation khớp; test intervention; huấn luyện lại từng thiết kế với group mới.'),('11. Tổng hợp và báo cáo','So sánh paired theo subject, trình bày mọi seeds và giới hạn.','Dẫn đúng canonical/đối chứng, không chọn group tốt nhất theo Test; báo cáo source/data/environment/protocol.')],[3.1,7,6.9])
    p('Thứ tự trên điều chỉnh yêu cầu ban đầu theo thực tế: kiểm tra dữ liệu đã có một phần và GRU đã thực thi một lượt. Không lặp lại vô điều kiện phần đã hoàn tất. Những bước về arrays/raw, chạy model, tạo cache, thay source và mở nghiên cứu mới đều nằm ngoài nhiệm vụ chỉ đọc và biên soạn giáo trình này.')
    ending('Ví dụ giả thuyết tương lai, chưa thực hiện: “CNN-GRU có tăng Macro-F1 trung bình theo người dưới cùng ngân sách tuning không?” Trước chạy phải ghi kiến trúc, seeds, ngân sách, metric và cách xử lý các lượt lỗi. Sau chạy mới điền điểm; một dòng kế hoạch không được chứa score giả định như kết quả.',
      'Roadmap ưu tiên làm rõ dữ liệu và giao thức, bảo toàn E1 rồi mới mở thiết kế mới. E2 đã có lượt đầu; E3 và ablation còn là công việc tương lai.',
      ['Bước nào phải hoàn tất trước khi dùng điểm CNN hai khối trong báo cáo?','Một ablation làm giảm số kênh có kiểm tra cùng giả thuyết với zero-after-scaling không?','Bạn sẽ ghi những gì trước khi thực hiện một lượt GRU mới?'])
